text:
{{
  (() => {
    const raw = currentItem.wifi_signal;

    if (raw === null || raw === undefined || raw === "") {
      return "No WiFi data";
    }

    const signal = Number(String(raw).replace("dBm", "").trim());

    if (isNaN(signal)) {
      return "No WiFi data";
    }

    let rating = "";

    if (signal >= -50) rating = "Excellent";
    else if (signal >= -60) rating = "Okay";
    else if (signal >= -70) rating = "Marginal";
    else if (signal >= -75) rating = "Bad";
    else rating = "Unserviceable";

    return `${signal} dBm - ${rating}`;
  })()
}}

textColor:
{{
  (() => {
    const raw = currentItem.wifi_signal;

    if (raw === null || raw === undefined || raw === "") {
      return "#6B7280";   // grey / no data
    }

    const signal = Number(String(raw).replace("dBm", "").trim());

    if (isNaN(signal)) {
      return "#6B7280";   // grey / no data
    }

    if (signal >= -50) return "#16A34A";   // green
    if (signal >= -60) return "#84CC16";   // yellow-green
    if (signal >= -70) return "#FACC15";   // yellow
    if (signal >= -75) return "#F97316";   // orange
    return "#DC2626";                      // red
  })()
}}
